import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { inventoryAPI } from '../services/api';
import SkinDetailModal from '../components/SkinDetailModal';
import ImageWithFallback from '../components/ImageWithFallback';

const InventoryPage = () => {
  const { balance } = useAuth();
  const navigate = useNavigate();
  const [inventory, setInventory] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedItem, setSelectedItem] = useState(null);

  useEffect(() => {
    const fetchInventory = async () => {
      try {
        const inventoryResponse = await inventoryAPI.getInventory();
        setInventory(inventoryResponse.data);
      } catch (error) {
        console.error('Error fetching inventory:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchInventory();
  }, []);

  const handleItemDetail = (inventoryItem) => {
    setSelectedItem(inventoryItem.item);
  };

  const handleCloseDetail = () => {
    setSelectedItem(null);
  };

  const handleUpgradeItem = () => {
    setSelectedItem(null);
    navigate('/upgrade');
  };

  if (loading) {
    return (
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-md-4">
            <div className="text-center py-5">
              <div className="spinner-border text-primary" role="status">
                <span className="visually-hidden">Loading...</span>
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container">
      <h1 className="mb-4 gradient-text">Inventory</h1>
      <div className="alert alert-info">
        Virtual currency — no real-money value
      </div>
      <div className="row mb-4">
        <div className="col-md-8">
          <h2>Balance: <span className="text-success">{balance.toLocaleString()} €</span></h2>
        </div>
      </div>

      {/* Inventory Filters */}
      <div className="row mb-4">
        <div className="col-12">
          <div className="btn-group btn-group-toggle" data-toggle="buttons">
            <label className="btn btn-outline-primary active">
              <input type="radio" name="options" defaultChecked /> All             </label>
            <label className="btn btn-outline-primary">
              <input type="radio" name="options" /> Mil-Spec             </label>
            <label className="btn btn-outline-primary">
              <input type="radio" name="options" /> Restricted             </label>
            <label className="btn btn-outline-primary">
              <input type="radio" name="options" /> Classified             </label>
            <label className="btn btn-outline-primary">
              <input type="radio" name="options" /> Covert             </label>
            <label className="btn btn-outline-primary">
              <input type="radio" name="options" /> Knives             </label>
            <label className="btn btn-outline-primary">
              <input type="radio" name="options" /> Gloves             </label>
            <label className="btn btn-outline-primary">
              <input type="radio" name="options" /> StatTrak             </label>
          </div>
        </div>
      </div>

      {/* Inventory Grid */}
      <div className="row g-4">
        {inventory.length > 0 ? (
          inventory.map(item => (
            <div key={item.id} className="col-md-3 col-sm-6">
              <div className="card hover-lift shine" onClick={() => handleItemDetail(item)}>
                <div className="card-body text-center p-3">
                  <ImageWithFallback
                       src={item.item?.image_url}
                       alt={item.item?.name || 'Unknown Item'}
                       className="item-image img-fluid"
                       style={{ maxWidth: '80px', maxHeight: '80px' }}
                  />
                  <h6 className="card-title mt-3">{item.item?.name || 'Unknown Item'}</h6>
                  <p className="text-muted small mb-2">{item.item?.category || ''}</p>
                  <div className="mb-3">
                    <span className={`badge bg-${item.item?.rarity?.toLowerCase() || 'secondary'} fs-6 px-3 py-1`}>
                      {item.item?.rarity || 'Common'}
                    </span>
                  </div>

                  <div className="mb-2">
                    <small className="text-muted">Float: {item.item?.float_value?.toFixed(4) || 'N/A'}</small>
                  </div>
                </div>
              </div>
            </div>
          ))
        ) : (
          <div className="col-12">
            <div className="text-center py-5">
              <h3>Your inventory is empty</h3>
              <p className="text-muted">Open some cases to get started!</p>
            </div>
          </div>
        )}
      </div>

      {/* Skin Detail Modal */}
      {selectedItem && (
        <SkinDetailModal 
          skin={selectedItem} 
          onClose={handleCloseDetail} 
          onUpgrade={handleUpgradeItem} 
        />
      )}
    </div>
  );
};

export default InventoryPage;
